  }
  getPos(key: string): number {
    const pos = this.#pos.get(key);
    if (pos === undefined) {
      throw new Error(`SymbolIds does not contain key: ${key}`);
    }
    return pos;
  }
  set(key: string, value: number, pos: number): void {
    this.#map.set(key, value);
    this.#pos.set(key, pos);
