        return self.print(colors=True)

    def _iterate_over_pointers(
        self, pointers: Pointers
    ) -> Iterator[Tuple[Any, List[GraphPointer]]]:
        # rules are de-duplicated by reference when the graph is built, so grouping by
        # identity groups every pointer that shares a rule.
